record.field:
website = env.ref('florist.website_industry')
to_deactivate = [ 'website.header_call_to_action', 'website.header_search_box', 'website.header_text_element', 'website.homepage', 'website.contactus', ] to_activate = [ 'website.footer_copyright_content_width_fluid', 'website.footer_no_copyright', 'website.template_header_default_align_center', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
menus = env['website.menu'] base_domain = [('website_id', '=', website.id)]
# Rename/reorder the default menu items, create the missing ones top_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1) menu_labels = [ ('/', 'Home', 10), ('/contactus', 'Contact us', 60), ] for url, name, sequence in menu_labels: menu = menus.search(base_domain + [('url', '=', url)], limit=1) if menu: menu.write({'name': name, 'sequence': sequence}) else: menus.create({ 'name': name, 'url': url, 'sequence': sequence, 'website_id': website.id, 'parent_id': top_menu.id if top_menu else False, })
